"Màn hình này là bản chuẩn bị dữ liệu nội bộ. Nó không phải chứng nhận, kết luận đảm bảo, hồ sơ hải quan đã chấp nhận hoặc bằng chứng đã được bên xác minh độc lập xác nhận. Chỉ chứng từ thật đã duyệt và có SHA-256 mới được hiển thị; chức năng tải chỉ mở sau khi máy chủ tạo, lưu và kiểm tra manifest cùng bundle bất biến. Chữ ký Ed25519 ở đây là platform attestation nội bộ; external assurance chỉ phản ánh bản ghi và statement đã gắn, không biến WeaveCarbon thành tổ chức chứng nhận.": "This screen is an internal data-preparation view. It is not a certification, an assurance conclusion, an accepted customs filing or evidence confirmed by an independent verifier. Only real, approved documents with SHA-256 hashes are shown; downloads unlock only after the server has generated, stored and checked the manifest and the immutable bundle. The Ed25519 signature here is an internal platform attestation; external assurance only reflects the attached records and statements and does not make WeaveCarbon a certification body.",
