"Lưu ý vi sợi nhựa": "Microfibre note",
"Sản phẩm sợi tổng hợp tái chế cơ học phát tán vi nhựa cao hơn (gấp 4–6 lần) khi giặt. Ưu tiên tặng để tái sử dụng nguyên trạng thay vì tái chế, và dùng túi giặt lọc vi nhựa để giảm phát tán.": "Mechanically recycled synthetic products shed more microplastics (4–6×) when washed. Prefer donating for reuse as-is rather than recycling, and use a microfibre-filtering wash bag to reduce shedding.",
"Sợi tổng hợp giải phóng vi sợi nhựa khi giặt. Cân nhắc dùng túi giặt lọc vi nhựa; nếu sản phẩm còn mặc được, hãy chọn quyên góp tái sử dụng (charity) để giữ nguyên cấu trúc sợi.": "Synthetic fibres release microplastic fibres when washed. Consider a microfibre-filtering wash bag; if the item is still wearable, choose a reuse (charity) donation to keep the fibre structure intact.",
"Ước tính theo mức tái sử dụng bảo thủ (WRAP): ~50% phát thải nguyên sinh tránh được.": "Estimated on a conservative reuse basis (WRAP): ~50% of virgin emissions avoided.",
"Ước tính theo tái chế cơ học (WRAP): ~0,7 kg CO₂/kg.": "Estimated on a mechanical recycling basis (WRAP): ~0.7 kg CO₂/kg.",
