"/tCO2e cao hơn chi phí giảm phát thải của các sáng kiến biến tần và bọc bảo ôn (MACC < 0 $/tCO2e). Doanh nghiệp nên kích hoạt ngay sáng kiến giảm thiểu nội bộ để xóa bỏ khoản thâm hụt": "/tCO2e, higher than the abatement cost of the VFD and insulation initiatives (MACC < $0/tCO2e). The company should activate internal mitigation initiatives now to eliminate the shortfall of",
": Bạn có thể tạo sáng kiến giảm thiểu, xây dựng kịch bản dự phóng, phân bổ hạn ngạch và tính vị thế phát thải. Dữ liệu lưu trong bộ nhớ tạm (tự động xóa sau 1 giờ hoặc khi đăng xuất).": ": You can create mitigation initiatives, build projection scenarios, allocate allowances and calculate the emission position. Data is kept in temporary storage (cleared automatically after 1 hour or on sign-out).",
": Các dự án có suất chi phí âm ($/tCO2e < 0) là những khoản đầu tư sinh lời trực tiếp từ việc cắt giảm chi phí năng lượng. Doanh nghiệp nên ưu tiên triển khai toàn bộ nhóm này trước khi đầu tư các giải pháp năng lượng tái tạo quy mô lớn.": ": Projects with a negative cost ($/tCO2e < 0) are investments that pay back directly through energy cost savings. The company should prioritise this whole group before investing in large-scale renewable energy.",
