"Kết quả CO₂e trên dashboard là phép tính nội bộ có tham chiếu một số nguyên tắc của ISO 14067 và GHG Protocol. Phạm vi hiện chưa đầy đủ; một số đầu vào và hệ số vẫn là dữ liệu proxy. Cần kiểm tra quyền sử dụng nguồn hệ số, bổ sung chứng từ gốc, rà soát phạm vi và có xác minh độc lập trước mọi công bố bên ngoài.": "CO₂e results on the dashboard are internal calculations referencing certain ISO 14067 and GHG Protocol principles. The scope is not yet complete; some inputs and factors are still proxy data. Check usage rights for factor sources, add original documents, review the scope and obtain independent verification before any external disclosure.",
