"1) Giữ nguyên tiêu đề cột.": "1) Keep the column headers unchanged.",
"10) SKU mẫu được sinh mới mỗi lần tải để tránh trùng.": "10) Sample SKUs are generated fresh on each download to avoid duplicates.",
"2) Cột bắt buộc được đánh dấu *.": "2) Required columns are marked with *.",
"3) Dùng giá trị mã trong sheet 'Allowed Values' để tương thích tốt nhất.": "3) Use the code values in the 'Allowed Values' sheet for best compatibility.",
"4) Với dòng xuất khẩu: đặt marketType=export và exportCountry.": "4) For export rows: set marketType=export and exportCountry.",
"5) processes / certifications / exportComplianceDocuments nhận nhiều giá trị, ngăn bằng dấu phẩy.": "5) processes / certifications / exportComplianceDocuments accept multiple values, separated by commas.",
"6) accessoriesWeightGram theo thứ tự accessories (vd accessories=button,zipper và weights=2,5).": "6) accessoriesWeightGram follows the order of accessories (e.g. accessories=button,zipper and weights=2,5).",
"7) Cột transportMode / transportDistanceKm là tuỳ chọn; để trống thì logistics để hoàn thiện sau.": "7) The transportMode / transportDistanceKm columns are optional; leave them blank to complete logistics later.",
