"Chọn độc lập đối tượng báo cáo và khoảng thời gian: toàn ngành, cơ sở, sản phẩm, lô sản xuất hoặc shipment; theo tháng, quý hoặc YTD. WeaveCarbon resolve lineage trước, sau đó mới tổng hợp dữ liệu và áp dụng report contract theo ngành/thị trường.": "Independently choose the reporting entity and time range: whole industry, facility, product, production batch or shipment; by month, quarter or YTD. WeaveCarbon resolves lineage first, then aggregates the data and applies the report contract for the industry/market.",
"Các kịch bản dưới đây dùng chung bộ dữ liệu demo công nghiệp & nông nghiệp 2026. Bấm để khóa phạm vi và dựng báo cáo ngay.": "The scenarios below share the 2026 industrial & agricultural demo dataset. Click to lock the scope and build the report immediately.",
