": Bạn có thể tạo hồ sơ MRV, lập kế hoạch đo đạc và tạo hồ sơ nộp báo cáo thử nghiệm. Dữ liệu lưu trong bộ nhớ tạm (tự động xóa sau 1 giờ hoặc khi đăng xuất).": ": You can create MRV records, plan monitoring and create trial report submissions. Data is kept in temporary storage (cleared automatically after 1 hour or on sign-out).",
"AI Chẩn đoán Nghĩa vụ Kiểm kê KNK Quốc gia (QĐ 13/2024 & QĐ 42/2026)": "AI diagnosis of national GHG inventory obligations (Decision 13/2024 & Decision 42/2026)",
"AI Chẩn đoán: Tổng năng lượng {0} TOE, phát thải {1} tCO2e. {2}": "AI diagnosis: total energy {0} TOE, emissions {1} tCO2e. {2}",
