"Upload vận đơn cho lô LOT-EU-2026-001": "Upload the bill of lading for lot LOT-EU-2026-001",
"Xác nhận hệ số phát thải điện đang dùng": "Confirm the electricity emission factor in use",
"Đảm bảo bao jumbo đạt tải trọng và tiêu chuẩn chống ẩm của khách hàng.": "Ensure jumbo bags meet the customer's load and moisture-resistance standards.",
"Đảm bảo tổng tỷ lệ vật liệu bằng 100% và giảm sai lệch Scope 3.": "Ensure material shares total 100% and reduce Scope 3 variance.",
"Đổi bao PP nhiều lớp sang bao jumbo tái sử dụng cho xi măng và phân bón.": "Switch multi-layer PP bags to reusable jumbo bags for cement and fertiliser.",
"Ước tính dựa trên Ecoinvent v3.10; cần thẩm tra với hóa đơn thực tế.": "Estimated from Ecoinvent v3.10; needs verification against actual invoices.",
"**Nguyên nhân chính:** - Phát thải quá trình và nhiên liệu tại lò điện hồ quang, lò nung clinker và cụm tổng hợp amoniac (Scope 1) - Điện lưới cho điện phân/ép đùn nhôm (Scope 2) - Phôi nhôm nguyên sinh và quặng nhập khẩu (Scope 3 upstream)": "**Main causes:** - Process and fuel emissions at the electric arc furnace, clinker kiln and ammonia synthesis unit (Scope 1) - Grid electricity for aluminium electrolysis/extrusion (Scope 2) - Primary aluminium billets and imported ore (upstream Scope 3)",
"**Nguyên nhân:** - Lượng phân đạm trên mỗi tấn sản phẩm cao (Scope 3 upstream) - Ruộng lúa ngập liên tục làm tăng CH₄ - Sấy bằng củi/than tại cơ sở sơ chế": "**Causes:** - High nitrogen fertiliser use per tonne of product (upstream Scope 3) - Continuously flooded rice paddies increase CH₄ - Wood/coal drying at primary processing facilities",
"**Nhận định:** Cường độ phát thải của danh mục demo tập trung ở thép, nhôm và phân bón — ba nhóm hàng thuộc phạm vi EU CBAM.": "**Assessment:** Emission intensity in the demo portfolio is concentrated in steel, aluminium and fertilisers — three goods groups within EU CBAM scope.",
"**Nhận định:** Với nông sản (cà phê, gạo, điều, cao su), phát thải tập trung ở giai đoạn canh tác: N₂O từ phân đạm và CH₄ từ ruộng lúa ngập nước.": "**Assessment:** For agricultural products (coffee, rice, cashew, rubber), emissions are concentrated in cultivation: N₂O from nitrogen fertiliser and CH₄ from flooded rice paddies.",
"**Đề xuất giảm phát thải (theo thứ tự ưu tiên):** 1. Tăng tỷ lệ thép phế và nhôm tái chế — giảm 25–40% phát thải nguyên liệu 2. Hợp đồng điện tái tạo (DPPA) hoặc điện mặt trời áp mái — giảm Scope 2 3. Thu hồi nhiệt thải lò nung và tối ưu tỷ lệ clinker/phụ gia": "**Recommended reductions (in priority order):** 1. Increase steel scrap and recycled aluminium — cuts material emissions by 25–40% 2. Renewable power contracts (DPPA) or rooftop solar — reduces Scope 2 3. Kiln waste heat recovery and optimised clinker/additive ratio",
"**Đề xuất:** 1. Thu thập dữ liệu nông hộ + toạ độ vườn (đồng thời đáp ứng EUDR) 2. Canh tác lúa ướt-khô xen kẽ (AWD) để giảm CH₄ 3. Chuyển máy sấy sang biomass/điện tái tạo": "**Recommendations:** 1. Collect smallholder data + farm coordinates (also meeting EUDR) 2. Alternate wetting and drying (AWD) rice cultivation to cut CH₄ 3. Switch dryers to biomass/renewable electricity",
"AI đã trích xuất hóa đơn 500 tấn thép phế liệu (HS 7204) từ nhà cung ứng Phế liệu Hoà Phát.": "AI extracted an invoice for 500 tonnes of steel scrap (HS 7204) from supplier Hoa Phat Scrap.",
"AI đã trích xuất thành công hóa đơn dầu Diesel với khối lượng 1,250 lít phục vụ lò hơi sản xuất.": "AI successfully extracted a diesel invoice for 1,250 litres used by the production boiler.",
"AI đã trích xuất thành công hóa đơn tiền điện EVN với sản lượng 38,500 kWh, hệ số phát thải 0.6592 kg CO₂e/kWh.": "AI successfully extracted an EVN electricity invoice for 38,500 kWh with an emission factor of 0.6592 kg CO₂e/kWh.",
"AI đã trích xuất vận đơn đường biển xuất khẩu tuyến Cát Lái - Hamburg, trọng lượng 18.5 tấn.": "AI extracted an export ocean bill of lading for the Cat Lai - Hamburg route, weight 18.5 tonnes.",
