"Báo cáo {0} này được dựng tự động từ lớp dữ liệu carbon được quản trị của WeaveCarbon cho ngành {1}, kỳ {2}. Kết quả bên trong là {3}; cấu trúc hồ sơ và căn cứ thị trường lấy từ reporting registry đã version.": "This {0} report was built automatically from WeaveCarbon's governed carbon data layer for the {1} industry, period {2}. Results inside are {3}; the record structure and market basis come from the versioned reporting registry.",
