"Dữ liệu được giữ nguyên giá trị gốc; AI chỉ hỗ trợ phân loại, đối chiếu và viết narrative, không sửa activity data hay kết quả deterministic calculation.": "Data keeps its original values; AI only helps classify, cross-check and write the narrative, and never modifies activity data or deterministic calculation results.",
"Electricity factor phải theo nơi tiêu thụ điện; target market không được dùng để chọn grid factor. Product PCF và corporate Scope 2 được giữ ở accounting context riêng.": "The electricity factor must follow where electricity is consumed; the target market must not be used to choose the grid factor. Product PCF and corporate Scope 2 are kept in separate accounting contexts.",
