"Liên kết bằng chứng": "Evidence links",
"Nguyên tắc chung: Activity Data × Emission Factor × conversion/allocation rule. GHG được quy đổi sang CO₂e theo accounting context và factor/GWP snapshot đã khóa cho calculation version.": "General principle: Activity Data × Emission Factor × conversion/allocation rule. GHGs are converted to CO₂e per the accounting context and the factor/GWP snapshot locked for the calculation version.",
"Phụ lục đầy đủ nên chứa Activity Data, Factor Registry, Evidence Register, Calculation Lineage, Legal References và Version/Change Log.": "A full appendix should contain Activity Data, the Factor Registry, Evidence Register, Calculation Lineage, Legal References and the Version/Change Log.",
