"Profile đã chọn không áp dụng cho ngành này.": "The selected profile does not apply to this industry.",
"Report không tự trở thành filing pháp lý, chứng nhận ISO hoặc tuyên bố independently verified. Các trạng thái đó chỉ được ghi nhận khi có quy trình/đơn vị có thẩm quyền tương ứng.": "A report does not by itself become a legal filing, an ISO certification or an independently verified statement. Those statuses are only recorded when the corresponding competent process/body is in place.",
