"Tách rõ chemicals nói chung và fertilisers thuộc CBAM. Report cần giữ product identity/CN code trước khi kích hoạt CBAM adapter.": "Clearly separate chemicals in general from CBAM-covered fertilisers. The report must keep product identity/CN code before activating the CBAM adapter.",
"Tổng phát thải được dùng trong view này là {0} tCO₂e; data completeness trung bình {1}%; evidence coverage ước tính {2}%.": "Total emissions used in this view are {0} tCO₂e; average data completeness {1}%; estimated evidence coverage {2}%.",
"WeaveCarbon chỉ tạo verification-ready package; không tự gắn trạng thái independently verified.": "WeaveCarbon only creates a verification-ready package; it never assigns an independently verified status itself.",
"WeaveCarbon đã tổng hợp dữ liệu tháng {0}, đối chiếu tính đầy đủ, bằng chứng, scope và market profile cho ngành {1}. Report có thể tiếp tục sang human review khi các blocker đã được xử lý.": "WeaveCarbon aggregated data for month {0}, cross-checking completeness, evidence, scope and market profile for the {1} industry. The report can proceed to human review once blockers are resolved.",
