"{0}% activity records ở mức Primary hoặc Evidence-backed.": "{0}% of activity records are Primary or Evidence-backed.",
"{0}/{1} activity records đang có factor key trực tiếp; các phép tính còn lại phải truy vết qua calculation snapshot.": "{0}/{1} activity records have a direct factor key; the remaining calculations must be traced via the calculation snapshot.",
"Áp dụng theo ngành / thị trường": "Applicability by industry / market",
"Đối tượng: Industry Pack {0}. Profile: {1}. Thị trường/phân khúc: {2}.": "Entity: Industry Pack {0}. Profile: {1}. Market/segment: {2}.",
"Ưu tiên PCF theo sản phẩm, dữ liệu vùng trồng (phân bón, tưới, sấy), truy xuất EUDR, logistics và dữ liệu hợp tác xã. Nông sản không thuộc CBAM.": "Prioritise product PCF, farm data (fertiliser, irrigation, drying), EUDR traceability, logistics and cooperative data. Agricultural goods are not covered by CBAM.",
"Ưu tiên clinker/cement production, calcination, kiln fuel mix, điện và clinker ratio. CBAM chỉ áp dụng khi hàng hóa/CN code thuộc phạm vi.": "Prioritise clinker/cement production, calcination, kiln fuel mix, electricity and clinker ratio. CBAM only applies when the goods/CN code are in scope.",
"Ưu tiên diesel khai trường, điện nghiền/sàng, sản lượng, ranh giới cơ sở và bằng chứng vận hành. Đầu ra chính là inventory/ISO/GHG hoặc buyer-specific khi phù hợp.": "Prioritise mine-site diesel, crushing/screening electricity, output, facility boundaries and operational evidence. The main outputs are inventory/ISO/GHG or buyer-specific where applicable.",
"Ưu tiên dữ liệu sản phẩm, nguyên liệu, điện/nhiên liệu, logistics và buyer PCF/ISO 14067 khi phù hợp. Không suy diễn CBAM cho toàn ngành vật liệu xây dựng.": "Prioritise product data, materials, electricity/fuel, logistics and buyer PCF/ISO 14067 where applicable. Do not infer CBAM for the whole construction materials sector.",
"Ưu tiên ranh giới cơ sở, nhiên liệu/nguyên liệu luyện kim, production route, sản lượng và CN code. Khi hàng hóa thuộc phạm vi EU CBAM, cần tách dữ liệu installation và embedded emissions theo profile áp dụng.": "Prioritise facility boundaries, metallurgical fuels/materials, production route, output and CN code. When goods are in EU CBAM scope, separate installation data and embedded emissions per the applicable profile.",
"Ưu tiên điện, nhiên liệu gia nhiệt, sản lượng, alloying inputs, installation và CN code. Với EU CBAM, chỉ tạo preparation pack cho hàng hóa thuộc scope.": "Prioritise electricity, heating fuel, output, alloying inputs, installation and CN code. For EU CBAM, only create a preparation pack for in-scope goods.",
"Ước tính coverage {0}% với {1} bản ghi bằng chứng.": "Estimated coverage {0}% with {1} evidence records.",
"Báo cáo được dựng từ snapshot dữ liệu đã quản trị của WeaveCarbon. AI hỗ trợ tổng hợp, đối chiếu và viết narrative; activity data, emission factors, calculation results và verification status không được AI tự tạo hoặc tự sửa.": "The report is built from WeaveCarbon's governed data snapshot. AI helps aggregate, cross-check and write the narrative; activity data, emission factors, calculation results and verification status are never created or modified by AI.",
"Chuyển kết quả đo lường thành hành động review và trạng thái phát hành rõ ràng.": "Turns measurement results into review actions and a clear release status.",
"Các kiểm tra dưới đây không thay đổi dữ liệu nguồn. Blocker giữ report ở trạng thái Draft; warning yêu cầu rà soát trước khi nâng trạng thái.": "The checks below do not change source data. Blockers keep the report in Draft; warnings require review before the status is raised.",
"Các nguồn dưới đây xác định cấu trúc/khả năng áp dụng của report profile. Dữ liệu doanh nghiệp bên trong vẫn phải được review theo kỳ và phạm vi thực tế.": "The sources below define the structure/applicability of the report profile. Company data inside must still be reviewed for the actual period and scope.",
