"Báo cáo {0} được dựng cho {1} “{2}”, phạm vi thời gian {3}. Hệ thống khóa đúng facility/product/batch/shipment lineage trước khi tổng hợp, vì vậy việc đổi report profile không làm thay đổi dữ liệu nguồn.": "The {0} report was built for {1} “{2}”, time scope {3}. The system locks the correct facility/product/batch/shipment lineage before aggregating, so changing the report profile does not change source data.",
"Carbon sản phẩm / batch": "Product / batch carbon",
"Chưa có sản lượng đủ để tính product/batch footprint độc lập.": "Not enough output data to calculate an independent product/batch footprint.",
"Cơ sở trong scope": "In-scope facilities",
"Cường độ carbon": "Carbon intensity",
"Kết quả kỳ được cộng từ cadence theo tháng trong phạm vi. Carbon intensity không được lấy trung bình đơn giản giữa các tháng; khi có production denominator, engine phải tính lại từ tổng phát thải / tổng sản lượng.": "Period results are summed from the in-scope monthly cadence. Carbon intensity is never simply averaged across months; when a production denominator exists, the engine recalculates from total emissions / total output.",
"Kết quả product/batch được suy ra từ số lượng trong scope và carbon intensity đã được quản trị. Allocation basis và intensity phải được khóa trong calculation snapshot trước khi phát hành thật.": "Product/batch results are derived from in-scope quantities and governed carbon intensity. The allocation basis and intensity must be locked in the calculation snapshot before a real release.",
"Loại phạm vi": "Scope type",
"Phát thải trong phạm vi report là {0} tCO₂e. Report sử dụng {1} activity records, {2} evidence records và {3} sản phẩm được ánh xạ trong scope.": "In-scope report emissions are {0} tCO₂e. The report uses {1} activity records, {2} evidence records and {3} products mapped in scope.",
"Phát thải trong scope": "In-scope emissions",
"Scope được resolve từ Carbon Evidence Graph theo thứ tự {0}. Chỉ dữ liệu thuộc {1} được đưa vào aggregation của kỳ này.": "Scope is resolved from the Carbon Evidence Graph in the order {0}. Only data belonging to {1} enters this period's aggregation.",
"Shipment report tách product embodied carbon và transport carbon trước khi cộng thành tổng phạm vi shipment, tránh double-counting giữa product footprint và logistics.": "Shipment reports separate product embodied carbon and transport carbon before summing the shipment scope total, avoiding double counting between product footprint and logistics.",
"Sản lượng / allocation basis": "Output / allocation basis",
"Sản lượng / số lượng": "Output / quantity",
"Sản phẩm trong scope": "In-scope products",
"Tháng thành phần": "Component months",
"Thị trường đích": "Target market",
"Thời gian và đối tượng là hai chiều độc lập: cùng một sản phẩm có thể tạo report tháng/quý/năm; một batch hoặc shipment giữ kỳ gắn với chính đối tượng đó để tránh trộn dữ liệu.": "Time and entity are independent dimensions: the same product can produce monthly/quarterly/annual reports; a batch or shipment keeps the period tied to that entity to avoid mixing data.",
"Toàn ngành / Industry Pack": "Whole industry / Industry Pack",
"WeaveCarbon thu thập {0} activity records và {1} evidence records sau khi áp dụng cả bộ lọc đối tượng lẫn thời gian. Dữ liệu ngoài scope không bị xoá; chúng chỉ không được đưa vào snapshot của report này.": "WeaveCarbon collected {0} activity records and {1} evidence records after applying both entity and time filters. Out-of-scope data is not deleted; it is simply not included in this report's snapshot.",
