"Bắt buộc khi cơ sở thuộc danh mục áp dụng. Tại ngày 13/09/2026, Quyết định 13/2024/QĐ-TTg vẫn là danh mục đang có hiệu lực; Quyết định 42/2026/QĐ-TTg có hiệu lực từ 25/09/2026.": "Mandatory when the facility is on the applicable list. As of 13/09/2026, Decision 13/2024/QD-TTg is still the list in force; Decision 42/2026/QD-TTg takes effect from 25/09/2026.",
