"CBAM hiện bao phủ cement, iron & steel, aluminium, fertilisers, electricity và hydrogen. Với Chemicals chỉ đánh dấu áp dụng khi sản phẩm thực tế là fertiliser thuộc CN code được bao phủ. Nông sản (cà phê, gạo, cao su) không phải ngành CBAM; áp dụng EUDR cho cà phê/cao su.": "CBAM currently covers cement, iron & steel, aluminium, fertilisers, electricity and hydrogen. For Chemicals, mark it applicable only when the actual product is a fertiliser under a covered CN code. Agricultural goods (coffee, rice, rubber) are not CBAM sectors; EUDR applies to coffee/rubber.",
