"Chào bạn! Mình là **Weavey**. Mình là trợ lý AI về phát triển bền vững của WeaveCarbon, sẵn sàng giúp bạn: - Tìm hiểu về **dấu chân carbon** và cách tính - Giải đáp về **quy định xuất khẩu xanh** - Hướng dẫn sử dụng **công cụ tính carbon** Bạn cứ hỏi mình nhé!": "Hello! I'm **Weavey**, WeaveCarbon's AI sustainability assistant, ready to help you: - Learn about **carbon footprints** and how to calculate them - Answer questions on **green export regulations** - Guide you through the **carbon calculator** Just ask!",
