"Đây là baseline phần mềm. Cần kiểm thử gateway thật, mTLS/key custody, mạng gián đoạn, OTA/rollback trên thiết bị và nghiệm thu hiệu chuẩn tại cơ sở trước khi gọi là production-grade.": "This is a software baseline. Real gateway testing, mTLS/key custody, intermittent networks, OTA/rollback on devices and on-site calibration acceptance are required before calling it production-grade.",
"Đây là bước tạm thay cho Camera AI. Bạn cần chọn một ảnh trước khi tiếp tục.": "This is a temporary step instead of Camera AI. You need to choose a photo before continuing.",
"Đây là công cụ chuẩn bị và kiểm soát nội bộ, không phải kết luận pháp lý, xác minh độc lập hay bằng chứng đã nộp hồ sơ.": "This is an internal preparation and control tool, not a legal conclusion, independent verification or proof of a filed record.",
"Đây là kết quả ước tính sơ bộ. Cập nhật dữ liệu để có kết quả chính xác hơn.": "This is a preliminary estimate. Update the data for more accurate results.",
"Đây là sàng lọc do người dùng gán mức ưu tiên, cần chuyên gia kiểm tra. ERA5-Land là reanalysis lịch sử và CMIP6 là dự phóng theo model/kịch bản; dữ liệu ở đây không phải cảm biến tại chỗ hay dự báo rủi ro đã được xác minh.": "This is user-assigned priority screening that requires expert review. ERA5-Land is historical reanalysis and CMIP6 is model/scenario projection; the data here is not on-site sensors or a verified risk forecast.",
